//! Integration tests for ICC profile writing: encode ↔ parse round trips,
//! invariants of generated bytes, deterministic output, concurrency and
//! error handling for malformed input.

use photocraft_cms::pipeline::Stage;
use photocraft_cms::profile::{Lut, LutKind};
use photocraft_cms::synth::{self, CmykParams};
use photocraft_cms::{Clut, CmsError, ColorSpace, Curve, Pcs, Profile, ProfileClass};

fn small_cmyk_params() -> CmykParams {
    CmykParams { grid_a2b: 2, grid_b2a: 2, ..Default::default() }
}

/// A cheap CMYK profile used as a base for mutation; generation is kept tiny.
fn base_profile() -> Profile {
    synth::cmyk_profile(&small_cmyk_params())
}

/// Builds a LUT with the requested dimensions and kind. The stage layout is
/// `[input curves, CLUT, output curves]`, which is accepted by all three LUT
/// encoders for both A2B and B2A directions.
fn make_lut(kind: LutKind, inputs: usize, outputs: usize) -> Lut {
    let grid: usize = 2;
    let data_len = grid.pow(inputs as u32) * outputs;
    let clut = Clut::new(vec![grid; inputs], outputs, vec![0.5f32; data_len]);
    Lut { kind, inputs, outputs, stages: vec![Stage::Curves(vec![Curve::Identity; inputs]), Stage::Clut(clut), Stage::Curves(vec![Curve::Identity; outputs])] }
}

fn parse_tag_offset(bytes: &[u8], sig: &[u8; 4]) -> Option<usize> {
    if bytes.len() < 132 {
        return None;
    }
    let count = u32::from_be_bytes([bytes[128], bytes[129], bytes[130], bytes[131]]) as usize;
    for i in 0..count {
        let off = 132 + i * 12;
        if &bytes[off..off + 4] == sig {
            let tag_off = u32::from_be_bytes([bytes[off + 4], bytes[off + 5], bytes[off + 6], bytes[off + 7]]) as usize;
            return Some(tag_off);
        }
    }
    None
}

#[test]
fn synthetic_cmyk_round_trip_preserves_header_fields() {
    let p = base_profile();
    let bytes = p.to_bytes();
    let q = Profile::parse(&bytes).expect("parse encoded profile");

    assert_eq!(q.class, ProfileClass::Output);
    assert_eq!(q.color_space, ColorSpace::Cmyk);
    assert_eq!(q.pcs, Pcs::Lab);
    assert_eq!(q.rendering_intent, p.rendering_intent);
    assert_eq!(q.description, p.description);
    assert_eq!(q.copyright, p.copyright);
    for (a, b) in q.white_point.iter().zip(p.white_point.iter()) {
        assert!((a - b).abs() < 1e-6, "white point changed: {a} != {b}");
    }
    assert_eq!(q.channels(), 4);
}

#[test]
fn synthetic_cmyk_round_trip_preserves_lut_presence() {
    let p = base_profile();
    let q = Profile::parse(&p.to_bytes()).expect("parse");
    for slot in q.a2b.iter().chain(q.b2a.iter()) {
        assert!(slot.is_some(), "expected a LUT in every slot");
    }
}

#[test]
fn synthetic_cmyk_lut_kind_is_lut16() {
    let p = base_profile();
    let q = Profile::parse(&p.to_bytes()).expect("parse");
    assert!(q.a2b.iter().all(|l| matches!(l.as_ref().map(|l| l.kind), Some(LutKind::Lut16))));
    assert!(q.b2a.iter().all(|l| matches!(l.as_ref().map(|l| l.kind), Some(LutKind::Lut16))));
}

#[test]
fn matrix_trc_rgb_round_trip() {
    let mut p = base_profile();
    p.color_space = ColorSpace::Rgb;
    p.pcs = Pcs::Xyz;
    p.a2b = [None, None, None];
    p.b2a = [None, None, None];
    let expected_matrix = [[0.4124, 0.3576, 0.1805], [0.2126, 0.7152, 0.0722], [0.0193, 0.1192, 0.9505]];
    p.matrix = Some(expected_matrix);
    p.trc = Some([Curve::Gamma(2.2), Curve::Gamma(2.2), Curve::Gamma(2.2)]);
    p.gray_trc = None;
    let bytes = p.with_encoded_bytes().to_bytes();

    let q = Profile::parse(&bytes).expect("parse matrix/TRC profile");
    assert_eq!(q.color_space, ColorSpace::Rgb);
    assert_eq!(q.pcs, Pcs::Xyz);
    assert!(q.matrix.is_some());
    assert!(q.trc.is_some());
    let m = q.matrix.unwrap();
    for row in 0..3 {
        for col in 0..3 {
            assert!((m[row][col] - expected_matrix[row][col]).abs() < 1e-4);
        }
    }
    for (a, b) in q.trc.as_ref().unwrap().iter().zip([Curve::Gamma(2.2), Curve::Gamma(2.2), Curve::Gamma(2.2)]) {
        match (a, &b) {
            (Curve::Gamma(x), Curve::Gamma(y)) => assert!((*x - *y).abs() < 1e-3, "gamma mismatch: {x} vs {y}"),
            other => panic!("expected Curve::Gamma, got {other:?}"),
        }
    }
    assert!(q.a2b.iter().all(Option::is_none));
    assert!(q.b2a.iter().all(Option::is_none));
}

#[test]
fn gray_trc_round_trip() {
    let mut p = base_profile();
    p.color_space = ColorSpace::Gray;
    p.pcs = Pcs::Xyz;
    p.a2b = [None, None, None];
    p.b2a = [None, None, None];
    p.matrix = None;
    p.trc = None;
    p.gray_trc = Some(Curve::Gamma(2.2));
    let bytes = p.with_encoded_bytes().to_bytes();

    let q = Profile::parse(&bytes).expect("parse gray profile");
    assert_eq!(q.color_space, ColorSpace::Gray);
    let parsed_gray = q.gray_trc.expect("gray_trc exists");
    match parsed_gray {
        Curve::Gamma(g) => assert!((g - 2.2).abs() < 1e-3, "gamma mismatch: {g}"),
        other => panic!("expected Curve::Gamma, got {other:?}"),
    }
    assert!(q.a2b.iter().all(Option::is_none));
    assert!(q.b2a.iter().all(Option::is_none));
}

