#[test]
fn rgb_lut8_mft_round_trip() {
    let mut p = base_profile();
    p.color_space = ColorSpace::Rgb;
    p.a2b = [None, None, None];
    p.b2a = [None, None, None];
    p.a2b[1] = Some(make_lut(LutKind::Lut8, 3, 3));
    let q = Profile::parse(&p.with_encoded_bytes().to_bytes()).expect("parse lut8 profile");
    let lut = q.a2b[1].as_ref().expect("a2b colorimetric LUT");
    assert_eq!(lut.kind, LutKind::Lut8);
    assert_eq!(lut.inputs, 3);
    assert_eq!(lut.outputs, 3);
}

